mapper.select:
SELECT CSI.ID , CSI.COURSE_STUDENT_ID , U.NAME AS STUDENT_NAME , CSI.INTERVIEW_COMPANY , TO_CHAR(CSI.INTERVIEW_DATE_TIME, 'YYYY-MM-DD HH24:MI') AS INTERVIEW_DATE_TIME FROM COURSE_STUDENT_INTERVIEWS CSI INNER JOIN COURSE_STUDENT CS ON CSI.COURSE_STUDENT_ID = CS.ID INNER JOIN "USER" U ON CS.USER_ID = U.ID WHERE CS.COURSE_ID = #{courseId}
AND CS.USER_ID = #{userId}
ORDER BY CSI.INTERVIEW_DATE_TIME ASC , CSI.ID ASC

SELECT COUNT(1)
  FROM COURSE_TUTOR CT
 WHERE CT.COURSE_ID = #{courseId}
   AND CT.TUTOR_ID = #{userId}

SELECT COUNT(1)
  FROM COURSE_STUDENT CS
 WHERE CS.COURSE_ID = #{courseId}
   AND CS.USER_ID = #{userId}
